.labelInput {
  position: relative;
  border: 1px solid #dcdee2;
  width: 250px;
  padding: 0 24px 0 8px;
  border-radius: 4px;
  min-height: 32px;
  cursor: pointer;

  .span {
    color: #c5c8ce;
  }

  .ivu-icon {
    position: absolute;
    top: 50%;
    right: 8px;
    line-height: 1;
    transform: translateY(-50%);
    font-size: 14px;
    color: #808695;
    transition: all 0.2s ease-in-out;
  }
}

.input-add {
  width: 250px;
  margin-right: 14px;
}

.style-add {
  margin-top: 10px;
